import{_ as r,o as t,c as a,a3 as n}from"./chunks/framework.z_KJ15Ep.js";const m=JSON.parse('{"title":"Früherer Import von Lehrerdaten aus Lehrer.txt","description":"","frontmatter":{"title":"Früherer Import von Lehrerdaten aus Lehrer.txt","source_pageid":862,"source_revision":7114},"headers":[],"relativePath":"hilfe/fruehere-verfahren/lehrer-txt-import.md","filePath":"hilfe/fruehere-verfahren/lehrer-txt-import.md"}'),i={name:"hilfe/fruehere-verfahren/lehrer-txt-import.md"};function h(s,e,o,d,l,u){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="fruherer-import-von-lehrerdaten-aus-lehrer-txt" tabindex="-1">Früherer Import von Lehrerdaten aus Lehrer.txt <a class="header-anchor" href="#fruherer-import-von-lehrerdaten-aus-lehrer-txt" aria-label="Permalink to &quot;Früherer Import von Lehrerdaten aus Lehrer.txt&quot;">​</a></h1><p>Dieser Artikel beschreibt den früheren Import von Lehrerdaten aus einer durch <strong>ASDPC</strong> erzeugten Datei mit Abteilungsdaten. Der dafür vorgesehene Schalter wurde aus der Lehrkräfteverwaltung entfernt.</p><p>Für den aktuellen Datenaustausch verwenden Sie die <a href="/schild3/import-export-statistik/schnittstelle-schild-vorbemerkungen.html">SchILD-NRW-Schnittstelle</a>. Die Felder der Datei <code>Lehrkraefte.dat</code> sind in der <a href="/schild3/import-export-statistik/schnittstellenbeschreibung.html#lehrkraefte-dat">Schnittstellenbeschreibung</a> erläutert.</p><h2 id="fruherer-importweg" tabindex="-1">Früherer Importweg <a class="header-anchor" href="#fruherer-importweg" aria-label="Permalink to &quot;Früherer Importweg&quot;">​</a></h2><p>Nach der damaligen Wiki-Beschreibung konnten die Grunddaten der Lehrkräfte – etwa Kürzel, Name und Adresse – alternativ zur Datei <code>Lehrkraefte.dat</code> aus einer ASDPC-Datei mit Abteilungsdaten übernommen werden.</p><p>In der Lehrkräfteverwaltung gab es dafür den Schalter <strong>Daten importieren aus „Lehrer.txt“</strong>.</p><h2 id="reihenfolge-beim-datenaustausch" tabindex="-1">Reihenfolge beim Datenaustausch <a class="header-anchor" href="#reihenfolge-beim-datenaustausch" aria-label="Permalink to &quot;Reihenfolge beim Datenaustausch&quot;">​</a></h2><p>Wurde dieser Importweg verwendet, konnte die Datei <code>Lehrkraefte.dat</code> entfallen. Der Import der Abteilungsdaten musste dann <strong>vor den übrigen Importen</strong> erfolgen, damit die benötigten Lehrkräfte bereits vorhanden waren.</p><p>Diese Beschreibung dient der Einordnung früherer Datenübernahmen. Der damalige Schalter steht für den aktuellen Arbeitsablauf nicht mehr zur Verfügung.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Schnittstellenbeschreibung" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7114.</p>',11)])])}const p=r(i,[["render",h]]);export{m as __pageData,p as default};
